"""Strict CPU/CUDA selection shared by local perception providers."""


class DeviceUnavailableError(RuntimeError):
    pass


def resolve_device(requested: str) -> str:
    if requested not in {"auto", "cpu", "cuda"}:
        raise ValueError("device must be one of: auto, cpu, cuda")
    if requested == "cpu":
        return "cpu"
    try:
        import torch
    except ImportError as exc:
        if requested == "cuda":
            raise DeviceUnavailableError(
                "CUDA was requested, but PyTorch is not installed. Install vir-vision[vision] "
                "with a CUDA-compatible PyTorch build."
            ) from exc
        return "cpu"
    available = bool(torch.cuda.is_available())
    if requested == "cuda" and not available:
        detail = f" (PyTorch {torch.__version__}, CUDA build {torch.version.cuda})"
        raise DeviceUnavailableError(
            "CUDA was requested, but torch.cuda.is_available() is false" + detail
        )
    return "cuda:0" if available else "cpu"


def synchronize(device: str) -> None:
    if not device.startswith("cuda"):
        return
    import torch

    torch.cuda.synchronize()
